302: /*
303:  * If any of hash field expiration command is called on a listpack hash object
304:  * for the first time, we convert it to OBJ_ENCODING_LISTPACK_EX encoding.
305:  * We allocate "struct listpackEx" which holds listpack pointer and metadata to
306:  * register key to the global DS. In the listpack, we append another TTL entry
307:  * for each field-value pair. From now on, listpack will have triplets in it:
308:  * field-value-ttl. If TTL is not set for a field, we store 'zero' as the TTL
309:  * value. 'zero' is encoded as two bytes in the listpack. Memory overhead of a
310:  * non-existing TTL will be two bytes per field.
311:  *
312:  * Fields in the listpack will be ordered by TTL. Field with the smallest expiry
313:  * time will be the first item. Fields without TTL will be at the end of the
314:  * listpack. This way, it is easier/faster to find expired items.
315:  */
316: 
317: #define HASH_LP_NO_TTL 0
318: 
319: struct listpackEx *listpackExCreate(void) {
320:     listpackEx *lpt = zcalloc(sizeof(*lpt));
321:     lpt->meta.trash = 1;
322:     lpt->lp = NULL;
323:     lpt->key = NULL;
324:     return lpt;
325: }
