1039: unsigned char *lpDeleteRange(unsigned char *lp, long index, unsigned long num) {
1040:     unsigned char *p;
1041:     uint32_t numele = lpGetNumElements(lp);
1042: 
1043:     if (num == 0) return lp; /* Nothing to delete, return ASAP. */
1044:     if ((p = lpSeek(lp, index)) == NULL) return lp;
