3202: /*
3203:  * Called after modifying fields to update global hfe DS if necessary
3204:  *
3205:  * minExpire: minimum expiry time of the key before modification
3206:  * minExpireFields: minimum expiry time of the modified fields
3207:  */
3208: static void updateGlobalHfeDs(redisDb *db, robj *o,uint64_t minExpire, uint64_t minExpireFields)
3209: {
3210:     /* If minimum HFE of the hash is smaller than expiration time of the
3211:      * specified fields in the command as well as it is smaller or equal
3212:      * than expiration time provided in the command, then the minimum
3213:      * HFE of the hash won't change following this command. */
3214:     if ((minExpire < minExpireFields))
3215:         return;
3216: 
3217:     /* retrieve new expired time. It might have changed. */
3218:     uint64_t newMinExpire = hashTypeGetNextTimeToExpire(o);
3219: 
3220:     /* Calculate the diff between old minExpire and newMinExpire. If it is
3221:      * only few seconds, then don't have to update global HFE DS. At the worst
3222:      * case fields of hash will be active-expired up to few seconds later.
3223:      *
3224:      * In any case, active-expire operation will know to update global
3225:      * HFE DS more efficiently than here for a single item.
3226:      */
3227:     uint64_t diff = (minExpire > newMinExpire) ?
3228:                     (minExpire - newMinExpire) : (newMinExpire - minExpire);
3229:     if (diff < HASH_NEW_EXPIRE_DIFF_THRESHOLD) return;
3230: 
3231:     if (minExpire != EB_EXPIRE_TIME_INVALID)
3232:         ebRemove(&db->hexpires, &hashExpireBucketsType, o);
3233:     if (newMinExpire != EB_EXPIRE_TIME_INVALID)
3234:         ebAdd(&db->hexpires, &hashExpireBucketsType, o, newMinExpire);
3235: }
