2853: /* This is the generic command implementation for HEXPIRE, HPEXPIRE, HEXPIREAT
2854:  * and HPEXPIREAT. Because the command second argument may be relative or absolute
2855:  * the "basetime" argument is used to signal what the base time is (either 0
2856:  * for *AT variants of the command, or the current time for relative expires).
2857:  *
2858:  * unit is either UNIT_SECONDS or UNIT_MILLISECONDS, and is only used for
2859:  * the argv[2] parameter. The basetime is always specified in milliseconds.
2860:  *
2861:  * Additional flags are supported and parsed via parseExtendedExpireArguments */
2862: static void hexpireGenericCommand(client *c, const char *cmd, long long basetime, int unit) {
2863:     long numFields = 0, numFieldsAt = 4;
2864:     long long expire; /* unix time in msec */
2865:     int expireSetCond = 0;
2866:     robj *hashObj, *keyArg = c->argv[1], *expireArg = c->argv[2];
2867: 
2868:     /* Read the hash object */
2869:     if ((hashObj = lookupKeyWriteOrReply(c, keyArg, shared.null[c->resp])) == NULL ||
2870:         checkType(c, hashObj, OBJ_HASH)) return;
2871: 
2872:     /* Read the expiry time from command */
2873:     if (getLongLongFromObjectOrReply(c, expireArg, &expire, NULL) != C_OK)
2874:         return;
2875: 
2876:     /* Check expire overflow */
2877:     if (expire > (long long) EB_EXPIRE_TIME_MAX) {
2878:         addReplyErrorExpireTime(c);
2879:         return;
2880:     }
2881: 
2882:     if (unit == UNIT_SECONDS) {
2883:         if (expire > (long long) EB_EXPIRE_TIME_MAX / 1000) {
2884:             addReplyErrorExpireTime(c);
2885:             return;
2886:         }
2887:         expire *= 1000;
2888:     } else {
2889:         if (expire > (long long) EB_EXPIRE_TIME_MAX) {
2890:             addReplyErrorExpireTime(c);
2891:             return;
2892:         }
2893:     }
2894: 
2895:     if (expire > (long long) EB_EXPIRE_TIME_MAX - basetime) {
2896:         addReplyErrorExpireTime(c);
2897:         return;
2898:     }
2899:     expire += basetime;
