1337: /* Move to the next entry in the hash. Return C_OK when the next entry
1338:  * could be found and C_ERR when the iterator reaches the end. */
1339: int hashTypeNext(hashTypeIterator *hi, int skipExpiredFields) {
1340:     if (hi->encoding == OBJ_ENCODING_LISTPACK) {
1341:         unsigned char *zl;
1342:         unsigned char *fptr, *vptr;
1343: 
1344:         zl = hi->subject->ptr;
1345:         fptr = hi->fptr;
1346:         vptr = hi->vptr;
1347: 
1348:         if (fptr == NULL) {
1349:             /* Initialize cursor */
1350:             serverAssert(vptr == NULL);
1351:             fptr = lpFirst(zl);
1352:         } else {
1353:             /* Advance cursor */
1354:             serverAssert(vptr != NULL);
1355:             fptr = lpNext(zl, vptr);
1356:         }
1357:         if (fptr == NULL) return C_ERR;
1358: 
1359:         /* Grab pointer to the value (fptr points to the field) */
1360:         vptr = lpNext(zl, fptr);
1361:         serverAssert(vptr != NULL);
1362: 
1363:         /* fptr, vptr now point to the first or next pair */
1364:         hi->fptr = fptr;
1365:         hi->vptr = vptr;
1366:     } else if (hi->encoding == OBJ_ENCODING_LISTPACK_EX) {
1367:         long long expire_time;
1368:         unsigned char *zl = hashTypeListpackGetLp(hi->subject);
1369:         unsigned char *fptr, *vptr, *tptr;
1370: 
1371:         fptr = hi->fptr;
1372:         vptr = hi->vptr;
1373:         tptr = hi->tptr;
1374: 
1375:         if (fptr == NULL) {
1376:             /* Initialize cursor */
1377:             serverAssert(vptr == NULL);
1378:             fptr = lpFirst(zl);
1379:         } else {
1380:             /* Advance cursor */
1381:             serverAssert(tptr != NULL);
1382:             fptr = lpNext(zl, tptr);
1383:         }
1384:         if (fptr == NULL) return C_ERR;
1385: 
1386:         while (fptr != NULL) {
